<head>
<meta charset=\"UTF-8\">
<title>Mini Savaş Oyunu</title>
<style>
  body {
    margin: 0;
    background: #111;
    overflow: hidden;
    font-family: Arial;
  }

  canvas {
    display: block;
    background: #4caf50;
  }

  #bilgi {
    position: fixed;
    top: 10px;
    left: 10px;
    color: white;
    font-size: 20px;
    z-index: 2;
  }
</style>
</head>

<body>

<div id=\"bilgi\">Can: ❤️ 100 | Skor: 0</div>
<canvas id=\"oyun\"></canvas>

<script>
const canvas = document.getElementById(\"oyun\");
const ctx = canvas.getContext(\"2d\");

canvas.width = innerWidth;
canvas.height = innerHeight;

let oyuncu = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  boyut: 35,
  hiz: 5,
  can: 100
};

let skor = 0;
let tuslar = {};
let mermiler = [];
let dusmanlar = [];

document.addEventListener(\"keydown\", e => {
  tuslar[e.key.toLowerCase()] = true;
});

document.addEventListener(\"keyup\", e => {
  tuslar[e.key.toLowerCase()] = false;
});

// Fareyle ateş et
canvas.addEventListener(\"click\", e => {
  let aci = Math.atan2(
    e.clientY - oyuncu.y,
    e.clientX - oyuncu.x
  );

  mermiler.push({
    x: oyuncu.x,
    y: oyuncu.y,
    hiz: 10,
    dx: Math.cos(aci),
    dy: Math.sin(aci)
  });
});

// Düşman oluştur
setInterval(() => {
  dusmanlar.push({
    x: Math.random() * canvas.width,
    y: Math.random() * canvas.height,
    boyut: 30,
    hiz: 1.5
  });
}, 1200);

function hareket() {

  if (tuslar[\"w\"] || tuslar[\"arrowup\"])
    oyuncu.y -= oyuncu.hiz;

  if (tuslar[\"s\"] || tuslar[\"arrowdown\"])
    oyuncu.y += oyuncu.hiz;

  if (tuslar[\"a\"] || tuslar[\"arrowleft\"])
    oyuncu.x -= oyuncu.hiz;

  if (tuslar[\"d\"] || tuslar[\"arrowright\"])
    oyuncu.x += oyuncu.hiz;

  oyuncu.x = Math.max(0, Math.min(canvas.width, oyuncu.x));
  oyuncu.y = Math.max(0, Math.min(canvas.height, oyuncu.y));
}

function oyun() {

  ctx.clearRect(0, 0, canvas.width, canvas.height);

  hareket();

  // Oyuncu
  ctx.fillStyle = \"blue\";
  ctx.fillRect(
    oyuncu.x - 17,
    oyuncu.y - 17,
    oyuncu.boyut,
    oyuncu.boyut
  );

  // Mermiler
  for (let mermi of mermiler) {
    mermi.x += mermi.dx * mermi.hiz;
    mermi.y += mermi.dy * mermi.hiz;

    ctx.fillStyle = \"yellow\";
    ctx.beginPath();
    ctx.arc(mermi.x, mermi.y, 6, 0, Math.PI * 2);
    ctx.fill();
  }

  // Düşmanlar
  for (let i = dusmanlar.length - 1; i >= 0; i--) {

    let d = dusmanlar[i];

    let aci = Math.atan2(
      oyuncu.y - d.y,
      oyuncu.x - d.x
    );

    d.x += Math.cos(aci) * d.hiz;
    d.y += Math.sin(aci) * d.hiz;

    ctx.fillStyle = \"red\";
    ctx.fillRect(
      d.x - 15,
      d.y - 15,
      d.boyut,
      d.boyut
    );

    // Düşman oyuncuya değerse
    let mesafe = Math.hypot(
      oyuncu.x - d.x,
      oyuncu.y - d.y
    );

    if (mesafe < 30) {
      oyuncu.can -= 1;
    }

    // Mermi düşmana çarparsa
    for (let j = mermiler.length - 1; j >= 0; j--) {

      let m = mermiler[j];

      let uzaklik = Math.hypot(
        m.x - d.x,
        m.y - d.y
      );

